24	// Upsert inserts incoming into the set keyed by id, or — when a fact with
25	// the same id already exists — unions the new provenance anchors into the
26	// existing fact and advances its UpdatedAt. Exact duplicates (same normalized
27	// text and paths) therefore collapse for free, which is what makes re-distilling
28	// a turn idempotent. It returns the updated set; the input slice may be reused.
29	//
30	// Upsert deliberately does not implement merge/supersede across *different*
31	// ids: that is the agent's judgment during distillation, handled separately.
32	func Upsert(records []Record, incoming Record) []Record {
33		for i := range records {
34			if records[i].ID != incoming.ID {
35				continue
36			}
37			records[i].Provenance = UnionAnchors(records[i].Provenance, incoming.Provenance)
38			if incoming.UpdatedAt.After(records[i].UpdatedAt) {
39				records[i].UpdatedAt = incoming.UpdatedAt
40			}
41			// Fill Kind from a re-distill when the stored fact lacks a valid one, but
42			// don't overwrite an existing valid kind (avoids thrash between an
43			// agent-labeled and an inferred value across runs).
44			if !ValidFactKind(records[i].Kind) && ValidFactKind(incoming.Kind) {
45				records[i].Kind = incoming.Kind
46			}
47			return records
48		}
49		return append(records, incoming)
50	}
51	
52	// UnionAnchors appends anchors from b that are not already present in a,
53	// preserving order. Anchors are compared on their identifying fields so the
54	// same source turn is never recorded twice.
55	func UnionAnchors(a, b []Anchor) []Anchor {
56		seen := make(map[string]struct{}, len(a)+len(b))
57		key := func(anchor Anchor) string {
58			return strings.Join([]string{anchor.SessionID, anchor.Commit, anchor.CheckpointID, anchor.TurnID, anchor.Transcript, fmt.Sprint(anchor.Line)}, "\x00")
59		}
60		out := make([]Anchor, 0, len(a)+len(b))
61		for _, anchor := range a {
62			k := key(anchor)
63			if _, ok := seen[k]; ok {
64				continue
65			}
66			seen[k] = struct{}{}
67			out = append(out, anchor)
68		}
69		for _, anchor := range b {
70			k := key(anchor)
71			if _, ok := seen[k]; ok {
72				continue
73			}
74			seen[k] = struct{}{}
75			out = append(out, anchor)
76		}
77		return out
