203	// WriteNDJSON sorts records deterministically (see Sort) and writes them as
204	// newline-delimited JSON, one record per line, so the output is stable across
205	// rebuilds and diffs cleanly. It performs no file or path handling — callers
206	// supply the writer.
207	//
208	// A record whose line would exceed MaxLineBytes is refused with
209	// ErrRecordTooLarge rather than written: ParseNDJSON could not read it back, and
210	// a store that writes what it cannot read is unrecoverable from the reading side.
211	func WriteNDJSON(w io.Writer, records []Record) error {
212		Sort(records)
213		// Preflight every record before writing, so validation failures leave the
214		// destination untouched. Discard each encoding after checking its size:
215		// retaining the full batch would duplicate the caller's output buffer.
216		for i, record := range records {
217			if field, value := invalidUTF8Field(record); field != "" {
218				return &InvalidUTF8Error{RecordID: record.ID, Index: i, Field: field, Value: value}
219			}
220			data, err := json.Marshal(record)
221			if err != nil {
222				return err
223			}
224			if len(data) > MaxLineBytes {
225				return fmt.Errorf("%w: %s is %d bytes, maximum %d", ErrRecordTooLarge, record.ID, len(data), MaxLineBytes)
226			}
227		}
228		// Re-encode one record at a time after the batch passes validation.
229		// Records must not be modified concurrently, as with the in-place Sort.
230		for _, record := range records {
231			data, err := json.Marshal(record)
232			if err != nil {
233				return err
234			}
235			if _, err := w.Write(data); err != nil {
236				return err
237			}
238			if _, err := w.Write([]byte{'\n'}); err != nil {
239				return err
240			}
241		}
242		return nil
243	}
