181	// setRootUsage preserves the workflow order without changing Cobra's global
182	// sorting setting or the default help for subcommands.
183	func setRootUsage(root *cobra.Command, commands []*cobra.Command) {
184		defaultUsage := root.UsageFunc()
185		defaultHelp := root.HelpFunc()
186		helpWidth := 0
187		root.SetHelpFunc(func(cmd *cobra.Command, args []string) {
188			// Cobra renders UsageString into a buffer; measure the real output first.
189			if cmd == root {
190				helpWidth = helpTerminalWidth(cmd.OutOrStdout())
191				defer func() { helpWidth = 0 }()
192			}
193			defaultHelp(cmd, args)
194		})
195		root.SetUsageFunc(func(cmd *cobra.Command) error {
196			if cmd != root {
197				return defaultUsage(cmd)
198			}
199			type helpEntry struct {
200				command *cobra.Command
201				name    string
202				group   string
203			}
204			var ordered []helpEntry
205			for _, c := range commands {
206				ordered = append(ordered, helpEntry{c, c.Name(), c.GroupID})
207				if c.Name() == "facts" {
208					// Surface operator paths without moving the everyday facts family
209					// or changing any child's registration or visibility.
210					for _, name := range []string{"import", "sync", "proposals", "gc", "vitality"} {
211						for _, child := range c.Commands() {
212							if child.Name() == name {
213								ordered = append(ordered, helpEntry{child, "facts " + name, "operations"})
214							}
215						}
216					}
217				}
218			}
219			for _, c := range cmd.Commands() {
220				if c.Name() == "help" {
221					ordered = append(ordered, helpEntry{c, c.Name(), c.GroupID})
222				}
223			}
224			var out strings.Builder
225			fmt.Fprintf(&out, "Usage:\n  %s\n  %s [command]\n", cmd.UseLine(), cmd.CommandPath())
226			width := 0
227			for _, entry := range ordered {
228				if !entry.command.Hidden && len(entry.name) > width {
229					width = len(entry.name)
230				}
231			}
232			terminalWidth := helpWidth
233			if terminalWidth == 0 {
234				terminalWidth = helpTerminalWidth(cmd.OutOrStderr())
235			}
236			for _, group := range cmd.Groups() {
237				fmt.Fprintf(&out, "\n%s\n", group.Title)
238				for _, entry := range ordered {
239					c := entry.command
240					if entry.group == group.ID && !c.Hidden && (c.IsAvailableCommand() || c.Name() == "help") {
241						writeHelpCommand(&out, entry.name, c.Short, width, terminalWidth)
242					}
243				}
244			}
245			if all, _ := cmd.Flags().GetBool("help-all"); all {
246				writeAllCommandHelp(&out, cmd, terminalWidth)
247			}
248			fmt.Fprintf(&out, "\nFlags:\n%s", cmd.LocalFlags().FlagUsages())
249			fmt.Fprintf(&out, "\nUse %q for more information about a command.\n", cmd.CommandPath()+" [command] --help")
250			_, err := io.WriteString(cmd.OutOrStderr(), out.String())
251			return err
252		})
253	}
