255	// List full paths without changing Hidden: all-help is an inspection surface,
256	// not a visibility change to the command tree or subsequent help invocations.
257	func writeAllCommandHelp(out io.Writer, root *cobra.Command, terminalWidth int) {
258		var commands []*cobra.Command
259		var paths []string
260		width := 0
261		var collect func(*cobra.Command, string)
262		collect = func(parent *cobra.Command, prefix string) {
263			for _, child := range parent.Commands() {
264				path := prefix + child.Name()
265				commands = append(commands, child)
266				paths = append(paths, path)
267				width = max(width, len(path))
268				collect(child, path+" ")
269			}
270		}
271		collect(root, "")
272		fmt.Fprintln(out, "\nAll commands (including developer and machine commands):")
273		for i, cmd := range commands {
274			writeHelpCommand(out, paths[i], cmd.Short, width, terminalWidth)
275		}
276	}
