351	func wrapJSONErrorRendering(cmd *cobra.Command) {
352		if cmd.Args != nil {
353			argsFunc := cmd.Args
354			cmd.Args = func(cmd *cobra.Command, args []string) error {
355				err := argsFunc(cmd, args)
356				if err == nil || !commandWantsJSONError(cmd) {
357					return err
358				}
359				_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
360				return renderedCommandError{err: err}
361			}
362		}
363		if cmd.RunE != nil {
364			run := cmd.RunE
365			cmd.RunE = func(cmd *cobra.Command, args []string) error {
366				err := run(cmd, args)
367				if err == nil || !commandWantsJSONError(cmd) {
368					return err
369				}
370				if commandErrorWasRendered(err) {
371					return err
372				}
373				_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
374				return renderedCommandError{err: err}
375			}
376		}
377		cmd.SetFlagErrorFunc(func(cmd *cobra.Command, err error) error {
378			if !commandWantsJSONError(cmd) {
379				return err
380			}
381			_ = writeCommandJSONError(cmd.ErrOrStderr(), err)
382			return renderedCommandError{err: err}
383		})
384		for _, child := range cmd.Commands() {
385			wrapJSONErrorRendering(child)
386		}
387	}
