389	func commandWantsJSONError(cmd *cobra.Command) bool {
390		if flag := cmd.Flags().Lookup("format"); flag != nil && flag.Changed {
391			if wants, ok := commandFormatFlagWantsJSON(flag.Value.String()); ok {
392				return wants
393			}
394		}
395		if flag := cmd.InheritedFlags().Lookup("format"); flag != nil && flag.Changed {
396			if wants, ok := commandFormatFlagWantsJSON(flag.Value.String()); ok {
397				return wants
398			}
399		}
400		if wants, ok := commandRawFormatWantsJSON(append(cmd.Flags().Args(), commandRawArgs(cmd)...)); ok {
401			return wants
402		}
403		if flag := cmd.Flags().Lookup("json"); flag != nil && flag.Changed {
404			return commandJSONFlagEnabled(flag.Value.String())
405		}
406		if flag := cmd.InheritedFlags().Lookup("json"); flag != nil && flag.Changed {
407			return commandJSONFlagEnabled(flag.Value.String())
408		}
409		for _, arg := range append(cmd.Flags().Args(), commandRawArgs(cmd)...) {
410			if arg == "--json" {
411				return true
412			}
413			if strings.HasPrefix(arg, "--json=") {
414				value := strings.TrimPrefix(arg, "--json=")
415				return value == "" || value == "true" || value == "1"
416			}
417		}
418		return false
419	}
