472	var commandErrorCodePattern = regexp.MustCompile(`^[a-z][a-z0-9_-]*$`)
473	
474	func writeCommandJSONError(w io.Writer, err error) error {
475		envelope := commandJSONError{
476			Code:    commandErrorCode(err),
477			Message: err.Error(),
478		}
479		data, marshalErr := json.MarshalIndent(envelope, "", "  ")
480		if marshalErr != nil {
481			return marshalErr
482		}
483		_, writeErr := fmt.Fprintln(w, string(data))
484		return writeErr
485	}
486	
487	func commandErrorCode(err error) string {
488		message := err.Error()
489		code, _, ok := strings.Cut(message, ":")
490		if ok {
491			code = strings.TrimSpace(code)
492			if commandErrorCodePattern.MatchString(code) {
493				return code
494			}
495		}
496		return "command_failed"
497	}
