		return "", nil, nil, false, fmt.Errorf("factsync: decode fact-set head %s/%s: %w", repoID, branch, err)
	}
	if !out.Found {
		return "", nil, nil, false, nil
	}
	return out.Ref, out.Data, out.Authors, true, nil
}

