294	func hookReadFailureTail(r io.Reader) string {
295		var tail []byte
296		buf := make([]byte, hookFailureTailBytes)
297		for {
298			n, err := r.Read(buf)
299			if n > 0 {
300				if len(tail)+n > hookFailureTailBytes {
301					tail = tail[len(tail)+n-hookFailureTailBytes:]
302				}
303				tail = append(tail, buf[:n]...)
304			}
305			if err == io.EOF {
306				return string(tail)
307			}
308			if err != nil {
309				return ""
310			}
311		}
312	}
313	
314	// hookMatchFailure ranks gotcha and closed-negative facts against the failure
315	// text. Only those two kinds are considered — a failure moment wants traps and
316	// dead ends, not conventions — and only scores at or above the precision bar
317	// survive.
318	func hookMatchFailure(facts []factRecord, query string) []factRecord {
319		queryLocus := factLocus(query)
320		type scored struct {
321			rec factRecord
322			n   int
323		}
324		var hits []scored
325		for _, f := range facts {
326			if f.Status != factStatusActive {
327				continue
328			}
329			switch factKindOrInferred(f) {
330			case factKindGotcha, factKindClosedNegative:
331			default:
332				continue
333			}
334			if score := factLexicalScore(f, query, queryLocus); score >= hookPostFailureMinScore {
335				hits = append(hits, scored{f, score})
336			}
337		}
338		sort.SliceStable(hits, func(i, j int) bool {
339			if hits[i].n != hits[j].n {
340				return hits[i].n > hits[j].n
341			}
342			return hits[i].rec.UpdatedAt.After(hits[j].rec.UpdatedAt)
343		})
344		out := make([]factRecord, len(hits))
345		for i, h := range hits {
346			out[i] = h.rec
347		}
348		return out
349	}
350	
351	// hookEmit writes the budget-capped emission: nothing at all when hits is
352	// empty (the silent default), else one compact line per fact (or a JSON
353	// object with --json). At least one fact is emitted when any matched, even if
354	// it alone exceeds the budget — an empty emission for a real match would be a
355	// false negative, the worse failure mode. It returns the facts actually
356	// emitted so the caller can leave serve receipts for exactly those.
357	func hookEmit(cmd *cobra.Command, hits []factRecord, budget int, jsonOut bool) ([]factRecord, error) {
358		if len(hits) == 0 {
359			return nil, nil
360		}
361		if budget <= 0 {
362			budget = hookDefaultBudgetTokens
363		}
364		kept := make([]factRecord, 0, len(hits))
365		spent := 0
366		for _, f := range hits {
367			cost := estimateTokens([]factRecord{f})
368			if len(kept) > 0 && spent+cost > budget {
369				break
370			}
371			kept = append(kept, f)
372			spent += cost
373		}
374		if jsonOut {
375			type hookFact struct {
376				ID    string   `json:"id"`
377				Kind  string   `json:"kind"`
378				Text  string   `json:"text"`
379				Paths []string `json:"paths,omitempty"`
380			}
381			out := struct {
382				Facts []hookFact `json:"facts"`
383			}{Facts: make([]hookFact, 0, len(kept))}
384			for _, f := range kept {
385				out.Facts = append(out.Facts, hookFact{ID: f.ID, Kind: factKindOrInferred(f), Text: f.Text, Paths: f.Paths})
386			}
387			return kept, writeJSON(cmd, out)
388		}
389		return kept, writeText(cmd, func(out io.Writer) {
390			for _, f := range kept {
391				fmt.Fprintf(out, "[%s] %s\n", factKindOrInferred(f), f.Text)
392			}
393		})
394	}
