func runSessionEndHook(t *testing.T, opts Options) (string, string) {
	t.Helper()
	cmd := newHookSessionEndCommand(opts)
	cmd.SetArgs([]string{"--session", "s1"})
	var out, errOut bytes.Buffer
	cmd.SetOut(&out)
	cmd.SetErr(&errOut)
	if err := cmd.Execute(); err != nil {
